items(242,[
I('P000384','theorem','Lemma 1: functoriality in the source and target',r'With fixed \(N\), \(\operatorname{Diff}_n^+(M,N)\) is contravariant in \(M\); with fixed \(M\), the pointwise module \(\operatorname{Diff}_n(M,N)\) is covariant in \(N\). One displayed composition is typed \(D\circ f:M_1\to M_2\).',r'For commutative unital \(K/R\), a \(K\)-linear map \(f:M_1\to M_2\) gives \(D\mapsto D\circ f\) from \(\operatorname{Diff}_n^+(M_2,N)\) to \(\operatorname{Diff}_n^+(M_1,N)\). A \(K\)-linear map \(g:N_1\to N_2\) gives \(D\mapsto g\circ D\) on the pointwise operator modules. Both maps preserve order and the stated scalar action.',r'These elementary functorial properties underpin \citet[\S1]{vinogradov1972logic}. Class A concerns the organized cojet presentation whose proof the November lecture supplies.',r'the functoriality is established. The target in the displayed first composition must be \(N\), a type error rather than a change to the theorem.',**{'class':'A'},literal_correctness='false as written',publication_match='exact',refs=V),
I('P000384','theorem','Lemma 2: first-order operators split into a derivation and multiplication',r'The notes prove \(A(ab)=aA(b)+bA(a)-abA(1)\) for \(A\in\operatorname{Diff}_1(K,M)\), its converse, and the corollary that \(A-A(1)\) is a derivation.',r'An \(R\)-linear map \(A:K\to M\) has order at most one exactly when this product formula holds for every \(a,b\in K\). Equivalently, \(A(a)=aA(1)+D(a)\) for a unique \(R\)-derivation \(D\). The subtraction in the corollary means the multiplication map \(a\mapsto aA(1)\), not a constant map.',r'This is an elementary consequence of the pre-1971 commutator calculus \citep[\S16.8]{grothendieck1967egaiv4}; the derivation functor is part of \citet[\S2]{vinogradov1972logic}. It is expository rather than a new first-order decomposition.',r'the equivalence holds over any commutative unital base, without dividing by 2 and without smoothness. The corrected reading of the subtraction is necessary for additivity.',literal_correctness='correct with missing hypotheses',publication_match='exact',refs=G+V),
I('P000384','theorem','Lemma 3: orders add under composition',r'For \(A\in\operatorname{Diff}_m(M_1,M_2)\) and \(B\in\operatorname{Diff}_n(M_2,M_3)\), the notes prove \(BA\in\operatorname{Diff}_{m+n}\) by induction and a commutator product rule. Here \(\delta_k\) has the opposite sign from P376.',r'For commutative \(K/R\), the composition of operators of orders at most \(m,n\) has order at most \(m+n\). With \(\delta_aT=T\circ a-a\circ T\), one has \(\delta_a(BA)=(\delta_aB)A+B(\delta_aA)\). The opposite convention gives the same order condition and the same formal product rule.',r'The filtered composition law is part of the earlier algebraic operator calculus \citep[\S16.8]{grothendieck1967egaiv4}. The lecture supplies its elementary inductive verification; \citet[\S3]{vinogradov1972logic} uses it to define Spencer differentials.',r'the order bound is established. Equality need not hold: principal symbols can vanish on composition. The local sign switch does not invalidate the argument.',literal_correctness='correct',publication_match='exact',refs=G+V),
I('P000385','theorem','Lemma 4: evaluation on cojets is a differential operator',r'The canonical map \(C:\operatorname{Diff}_n^+(K,N)\to N\), \(C(A)=A(1)\), is called an operator of order \(n\). The proof transfers its iterated commutators to those of \(A\).',r'With the precomposition \(K\)-module structure on the source, \(C\) has order at most \(n\). Composition with a \(K\)-linear \(f:M\to\operatorname{Diff}_n^+(K,N)\) therefore defines an order-at-most-\(n\) operator \(C\circ f:M\to N\), and this assignment is \(K\)-linear when the resulting operator module uses precomposition.',r'This evaluation map is the universal cojet operator in \citet[\S1]{vinogradov1972logic}. The proof given on the scan is a correct direct verification, using its chosen commutator sign.',r'the order bound is established. Exact order \(n\) is not asserted: it can drop for particular rings or modules.',**{'class':'A'},literal_correctness='correct with missing hypotheses',publication_match='exact',refs=V),
I('P000385','theorem','Lemma 5: currying an operator into a cojet-valued homomorphism',r'The map sends \(A\) to \(g_A(m)(k)=A(km)\); the notes check order, additivity, and scalar linearity. The first check is called restriction to a submodule.',r'For \(A\in\operatorname{Diff}_n^+(M,N)\), the map \(k\mapsto A(km)\) has order at most \(n\) because it is the composite of \(A\) with the \(K\)-linear map \(K\to M\), \(k\mapsto km\). The assignment \(m\mapsto g_A(m)\) is \(K\)-linear into the precomposition cojet module, and \(A\mapsto g_A\) is a homomorphism between the indicated operator and Hom modules. The map \(K\to M\) need not be injective.',r'This is the explicit forward direction of the universal cojet isomorphism published in \citet[\S1]{vinogradov1972logic}. The scan contains the three checks rather than merely announcing the universal property.',r'the construction is established for arbitrary unital modules. The word restriction should be replaced by precomposition with a module map; no torsion-free hypothesis on \(M\) is necessary.',**{'class':'A'},literal_correctness='correct with missing hypotheses',publication_match='exact',refs=V),
I('P000385-P000386','theorem','Lemma 6: the two cojet maps are mutually inverse',r'The lecture finishes by computing both composites and concludes \(\operatorname{Diff}_n^+N=\operatorname{Diff}_n^+(K,N)\) as the concrete universal cojet object.',r'For \(A:M\to N\), evaluation of its curried map gives \(g_A(m)(1)=A(m)\). Conversely, if \(g:M\to\operatorname{Diff}_n^+(K,N)\) is \(K\)-linear, then the curried form of \(C\circ g\) satisfies \((C\circ g)(km)=g(km)(1)=(k\cdot g(m))(1)=g(m)(k)\). Thus the two natural module maps are inverse.',r'The resulting isomorphism is exactly that stated in \citet[\S1]{vinogradov1972logic}. The November 1971 notebook provides an earlier detailed seminar proof; the paper was received in January 1972.',r'the proof is complete under the commutative-ring and fixed-base conventions already stated. The last equality is a realization of a universal object, not an assertion that the two scalar actions coincide.',**{'class':'A'},literal_correctness='correct',publication_match='exact',refs=V)
])
